transform.program:
# queue.star — join pipelines to merge requests by source branch, apply the
# deterministic urgency score, merge in the single enriched MR's reviewers_pending
# signal, and rank. Predeclared params: merge_requests, pipelines, notes (None when
# the notes step was skipped by `when:` in an engine that honors it — see
# rank.star/workflow.yaml), stalest, stale_before, total_open. Output via `result`.
#
# No date-math is available (Starlark here has no time/date module — see README
# SPEC-FEEDBACK #5), so staleness is a lexicographic string comparison against the
# caller-supplied stale_before threshold; this is valid because GitLab timestamps are
# consistently UTC / 'Z'-suffixed ISO 8601, which sorts correctly as plain strings.

_INFLIGHT_STATUSES = ["created", "waiting_for_resource", "preparing", "pending", "running", "scheduled"]

def _pipelines_by_ref(pipelines):
    best = {}
    for p in pipelines:
        ref = p.get("ref")
        if ref == None:
            continue
        cur = best.get(ref)
        if cur == None or p["id"] > cur["id"]:
            best[ref] = p
    return best

def _reviewers_pending(notes, mr_author):
    # True (nobody has weighed in) unless a non-system note from someone other than
    # the MR's own author exists.
    if notes == None or len(notes) == 0:
        return True
    for n in notes:
        if not n.get("system", False) and n.get("author") != mr_author:
            return False
    return True

def _score(pipeline_status, is_stale, reviewers_pending):
    score = 0
    if pipeline_status == "failed":
        score += 40
    elif pipeline_status == "no_pipeline_found":
        score += 10
    elif pipeline_status in _INFLIGHT_STATUSES:
        score += 5
    if is_stale:
        score += 25
    if reviewers_pending == True:
        score += 20
    return score

def _sort_key(row):
    # Ascending sort of (100 - score, updated_at) yields descending urgency with a
    # stalest-first tiebreak, using only operators/types this sandbox actually has.
    return (100 - row["urgency_score"], row["updated_at"])

def _build(merge_requests, pipelines, notes, stalest, stale_before, total_open):
    by_ref = _pipelines_by_ref(pipelines)
    stalest_iid = stalest["iid"]
    notes_list = notes if notes != None else []

    rows = []
    counts = {"failed_pipeline": 0, "stale": 0, "reviewers_pending_unknown": 0}

    for mr in merge_requests:
        pipeline = by_ref.get(mr["source_branch"])
        if pipeline == None:
            pipeline_status = "no_pipeline_found"
            pipeline_id = None
        else:
            pipeline_status = pipeline["status"]
            pipeline_id = pipeline["id"]

        is_stale = mr["updated_at"] < stale_before
        notes_checked = stalest_iid != 0 and mr["iid"] == stalest_iid

        if notes_checked:
            reviewers_pending = _reviewers_pending(notes_list, mr["author"])
            last_activity = mr["updated_at"]
            for n in notes_list:
                if n["created_at"] > last_activity:
                    last_activity = n["created_at"]
            last_activity_source = "mr_notes" if len(notes_list) > 0 else "mr_updated_at"
        else:
            reviewers_pending = None
            last_activity = mr["updated_at"]
            last_activity_source = "mr_updated_at"

        score = _score(pipeline_status, is_stale, reviewers_pending)

        if pipeline_status == "failed":
            counts["failed_pipeline"] += 1
        if is_stale:
            counts["stale"] += 1
        if reviewers_pending == None:
            counts["reviewers_pending_unknown"] += 1

        rows.append({
            "iid": mr["iid"],
            "title": mr["title"],
            "source_branch": mr["source_branch"],
            "target_branch": mr["target_branch"],
            "author": mr["author"],
            "created_at": mr["created_at"],
            "updated_at": mr["updated_at"],
            "pipeline_status": pipeline_status,
            "pipeline_id": pipeline_id,
            "is_stale": is_stale,
            "reviewers_pending": reviewers_pending,
            "notes_checked": notes_checked,
            "last_activity": last_activity,
            "last_activity_source": last_activity_source,
            "urgency_score": score,
        })

    ranked = sorted(rows, key=_sort_key)

    return {
        "queue": ranked,
        "summary": {
            "total_open": total_open,
            "considered": len(rows),
            "enriched_iid": stalest_iid if stalest_iid != 0 else None,
            "top_urgency_score": ranked[0]["urgency_score"] if len(ranked) > 0 else None,
            "counts": counts,
        },
    }

result = _build(merge_requests, pipelines, notes, stalest, stale_before, total_open)
